describe('Success Toast Notification After Saving Record', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="login-email"]').type('testuser@example.com');
    cy.get('[data-testid="login-password"]').type('password123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="dashboard"]').should('be.visible');
  });

  it('should display success toast notification when saving a valid record', () => {
    cy.get('[data-testid="create-record-button"]').click();
    cy.get('[data-testid="record-form"]').should('be.visible');

    cy.get('[data-testid="record-name-input"]').type('Test Record');
    cy.get('[data-testid="record-description-input"]').type('This is a test record');
    cy.get('[data-testid="record-email-input"]').type('record@example.com');

    cy.get('[data-testid="save-record-button"]').click();

    cy.get('[data-testid="toast-notification"]')
      .should('be.visible')
      .and('have.class', 'toast-success');

    cy.get('[data-testid="toast-message"]')
      .should('contain', 'Record saved successfully');

    cy.get('[data-testid="toast-icon"]')
      .should('have.class', 'icon-checkmark');

    cy.get('[data-testid="toast-notification"]', { timeout: 5000 })
      .should('not.exist');
  });

  it('should display success toast with correct styling and auto-dismiss after 5 seconds', () => {
    cy.get('[data-testid="create-record-button"]').click();
    cy.get('[data-testid="record-form"]').should('be.visible');

    cy.get('[data-testid="record-name-input"]').type('Styled Toast Test');
    cy.get('[data-testid="record-description-input"]').type('Testing toast styling');
    cy.get('[data-testid="record-email-input"]').type('styled@example.com');

    cy.get('[data-testid="save-record-button"]').click();

    cy.get('[data-testid="toast-notification"]')
      .should('be.visible')
      .and('have.css', 'background-color')
      .and('match', /rgb\(76, 175, 80\)|#4caf50/);

    cy.get('[data-testid="toast-notification"]')
      .should('have.css', 'position', 'fixed');

    cy.get('[data-testid="toast-close-button"]')
      .should('be.visible')
      .and('have.attr', 'aria-label', 'Close notification');

    cy.get('[data-testid="toast-notification"]').should('be.visible');
    cy.wait(5000);
    cy.get('[data-testid="toast-notification"]').should('not.exist');
  });

  it('should allow manual dismissal of success toast notification', () => {
    cy.get('[data-testid="create-record-button"]').click();
    cy.get('[data-testid="record-form"]').should('be.visible');

    cy.get('[data-testid="record-name-input"]').type('Manual Dismiss Test');
    cy.get('[data-testid="record-description-input"]').type('Testing manual dismiss');
    cy.get('[data-testid="record-email-input"]').type('dismiss@example.com');

    cy.get('[data-testid="save-record-button"]').click();

    cy.get('[data-testid="toast-notification"]').should('be.visible');

    cy.get('[data-testid="toast-close-button"]').click();

    cy.get('[data-testid="toast-notification"]').should('not.exist');
  });

  it('should handle multiple sequential saves with separate toast notifications', () => {
    for (let i = 1; i <= 3; i++) {
      cy.get('[data-testid="create-record-button"]').click();
      cy.get('[data-testid="record-form"]').should('be.visible');

      cy.get('[data-testid="record-name-input"]').type(`Record ${i}`);
      cy.get('[data-testid="record-description-input"]').type(`Description ${i}`);
      cy.get('[data-testid="record-email-input"]').type(`record${i}@example.com`);

      cy.get('[data-testid="save-record-button"]').click();

      cy.get('[data-testid="toast-notification"]')
        .should('be.visible')
        .and('have.class', 'toast-success');

      cy.get('[data-testid="toast-message"]')
        .should('contain', 'Record saved successfully');

      cy.wait(5000);
      cy.get('[data-testid="toast-notification"]').should('not.exist');
    }
  });

  it('should display toast with accessibility attributes', () => {
    cy.get('[data-testid="create-record-button"]').click();
    cy.get('[data-testid="record-form"]').should('be.visible');

    cy.get('[data-testid="record-name-input"]').type('Accessibility Test');
    cy.get('[data-testid="record-description-input"]').type('Testing a11y');
    cy.get('[data-testid="record-email-input"]').type('a11y@example.com');

    cy.get('[data-testid="save-record-button"]').click();

    cy.get('[data-testid="toast-notification"]')
      .should('have.attr', 'role', 'alert')
      .and('have.attr', 'aria-live', 'polite');

    cy.get('[data-testid="toast-message"]')
      .should('have.attr', 'id')
      .and('match', /toast-message-\d+/);
  });
});
